Consider the following C program:


```c
#include <stdio.h>
int compute(int k) {
    static int s = 2;
    if (k <= 0) return 1;
    s = s + k;
    return compute(k - 1) + s;
}
int main(void) {
    printf("%d\n", compute(7));
    return 0;
}
```

